import pathlib
import textwrap
from io import StringIO

import pytest
from ruamel.yaml import YAML, scalarstring

OPENAPI_HEADER = textwrap.dedent(
    """\
    #
    # DO NOT MODIFY BY HAND. This is autogenerated by FastAPI.
    #
    """
)


def convert_to_yaml(openapi_json) -> str:
    yaml = YAML(typ="rt")
    yaml.indent(mapping=2, sequence=4, offset=2)
    yaml.best_width = 200  # type: ignore[attr-defined]  # explicit width prevents output changes across ruamel versions
    # Walk the tree and make all multiline strings use block scalars.
    scalarstring.walk_tree(openapi_json)
    # Ruamel wants us to dump to a stream. We want a string. Meet in the
    # middle with StringIO.
    with StringIO() as stream:
        yaml.dump(openapi_json, stream)
        return stream.getvalue()


@pytest.mark.parametrize(
    ["given", "expected"],
    [
        (
            {"foo": ["bar", "baz"]},
            textwrap.dedent(
                """\
                foo:
                  - bar
                  - baz
                """
            ),
        ),
        (
            {"some_list": [{"a": 1, "b": 2, "c": {"c1": "foo", "c2": "bar"}}]},
            textwrap.dedent(
                """\
                some_list:
                  - a: 1
                    b: 2
                    c:
                      c1: foo
                      c2: bar
                """
            ),
        ),
        (
            {
                "multiline_string": textwrap.dedent(
                    """\
                    Twas brillig and the slithy toves
                    Did gyre and gimble in the wabe.
                    All mimsy were the borogoves
                    And the momeraths outgrabe.
                    """
                )
            },
            textwrap.dedent(
                """\
                multiline_string: |
                  Twas brillig and the slithy toves
                  Did gyre and gimble in the wabe.
                  All mimsy were the borogoves
                  And the momeraths outgrabe.
                """
            ),
        ),
    ],
)
def test_yaml_formatting(given, expected):
    actual = convert_to_yaml(given)
    assert actual == expected


@pytest.mark.anyio
async def test_spec_is_up_to_date(client, request):
    res = await client.get("/openapi.json")
    res.raise_for_status()
    as_yaml = convert_to_yaml(res.json())

    expected_file = OPENAPI_HEADER + as_yaml

    spec_file = pathlib.Path(__file__).parent.parent / "openapi.yaml"

    is_match = spec_file.read_text() == expected_file
    if not is_match and request.config.getoption("--update-openapi"):
        spec_file.write_text(expected_file)
    assert spec_file.read_text() == expected_file, textwrap.dedent(
        """\
        openapi.yaml does not match the spec generated by FastAPI.
        Any changes to the spec must be made via the python code.

        To update the spec, run

            pytest tests/test_openapi_spec.py --update-openapi

        """
    )


@pytest.mark.anyio
async def test_audit_event_level_is_an_enum(client):
    res = await client.get("/openapi.json")
    res.raise_for_status()

    event_level = res.json()["components"]["schemas"]["AuditEventLevel"]
    assert event_level["type"] == "string"
    assert event_level["enum"] == ["recovery", "operational"]


@pytest.mark.anyio
async def test_audit_sort_is_a_string_parameter(client):
    """Sort expressions stay strings in generated clients, not closed enums."""
    response = await client.get("/openapi.json")
    response.raise_for_status()
    parameters = response.json()["paths"]["/v1/audit/events"]["get"]["parameters"]
    schema = next(parameter["schema"] for parameter in parameters if parameter["name"] == "sort_by")
    assert schema["type"] == "string"
    assert "enum" not in schema
    assert schema["default"] == "event_produced_at:desc"
